%Dominykas Janulevičius EDIF-25/1 2026-09-30 17:00
%3 laboratorinis darbas
%%Priv uzd
%%1

%%a
figure(1); %[output:0c7bff84]
x = -pi:0.1:pi;
fx = tan(sin(x))+sin(tan(x));
plot(x, fx, 'y', 'LineWidth', 1.5); %[output:0c7bff84]
grid on; %[output:0c7bff84]
axis tight; %[output:0c7bff84]
xlabel('x'); %[output:0c7bff84]
ylabel('f(x)'); %[output:0c7bff84]
title('f(x) = tan(sin(x)) + sin(tan(x))'); %[output:0c7bff84]
legend('f(x)', 'Location', 'southoutside'); %[output:0c7bff84]

%%b
figure(2); %[output:7fbc93a7]
xb = 0:0.1:10;
fb1 = exp(-0.5*xb);
fb2 = sin(xb);
[ax, h1, h2] = plotyy(xb, fb1, xb, fb2, @semilogy, @plot); %[output:7fbc93a7]

grid on; %[output:7fbc93a7]
xlabel('x'); %[output:7fbc93a7]
ylabel(ax(1), 'f_1(x) = e^{-0.5x} (logaritminė Y ašis)'); %[output:7fbc93a7]
ylabel(ax(2), 'f_2(x) = sin(x) (tiesinė Y ašis)'); %[output:7fbc93a7]
title('Funkcijų f_1(x) ir f_2(x) grafikai'); %[output:7fbc93a7]
legend([h1, h2], 'f_1(x) = e^{-0.5x}', 'f_2(x) = sin(x)', 'Location', 'southoutside'); %[output:7fbc93a7]

%%2
figure(3); %[output:4622ca66]
N = 6;
M = 4;
A = rand(N, M);
subplot(2, 1, 1); %[output:4622ca66]
area(A); %[output:4622ca66]
title('Matricos ploto diagrama'); %[output:4622ca66]
xlabel('Eiluciu indeksas'); %[output:4622ca66]
ylabel('Sumine reiksme'); %[output:4622ca66]
grid on; %[output:4622ca66]

subplot(2, 1, 2); %[output:4622ca66]
mesh(A); %[output:4622ca66]
title('Matricos mesh diagrama'); %[output:4622ca66]
xlabel('Y Stulpelių indeksas'); %[output:4622ca66]
ylabel('X Eilučių indeksas'); %[output:4622ca66]
zlabel('Reiksme'); %[output:4622ca66]
grid on; %[output:4622ca66]

%%Pap uzd
%%1
t = 0:0.001:1;
A = 5; f = 5;
o = 1.5; U1 = 3; U2 = 2;
s = A*sin(2*pi*f*t);
n = o*randn(size(t));

sWN = s + n;

sf = sWN;
sf(abs(sf) < U2) = 0;

idx = find(sWN > U1);
ta  = t(idx);
a   = sWN(idx);

aMax = max(a);
aMin = min(a);
iMax = a == aMax;
iMin = a == aMin;

figure('Name', 'Signalu atvaizdavimas'); %[output:6fd8bb36]

%%a) Pradinis ir filtruotas signalai
subplot(2, 1, 1); %[output:6fd8bb36]
plot(t, sWN, '-.b', 'DisplayName', 'Pradinis signalas'); hold on; %[output:6fd8bb36]
plot(t, sf, '-', 'Color', 'y', 'DisplayName', 'Filtruotas signalas'); %[output:6fd8bb36]
yline(U1, 'Color', 'g', 'LineWidth', 1.5, 'DisplayName', 'Riba U_1'); %[output:6fd8bb36]
yline(U2, '--r', 'DisplayName', 'Riba U_2'); %[output:6fd8bb36]
hold off; %[output:6fd8bb36]
grid on; %[output:6fd8bb36]
title('Pradinis ir filtruotas signalai'); %[output:6fd8bb36]
xlabel('Laikas, s', 'Color', 'b', 'FontSize', 12); %[output:6fd8bb36]
ylabel('Itampa, V', 'Color', 'b', 'FontSize', 12); %[output:6fd8bb36]
legend('Location', 'best'); %[output:6fd8bb36]
xlim([t(1) t(end)]); %[output:6fd8bb36]
ylim([min(sWN) - 1, max(sWN) + 1]); %[output:6fd8bb36]

%%b) Reiksmes, virsijancios U1 (diskretus formatas)
subplot(2, 1, 2); %[output:6fd8bb36]
stem(ta, a, 'b', 'MarkerSize', 4, 'DisplayName', 'Reiksmes > U_1'); hold on; %[output:6fd8bb36]
plot(ta(iMax), a(iMax), 'ro', 'MarkerSize', 9, 'MarkerFaceColor', 'r', ... %[output:6fd8bb36]
    'DisplayName', 'Maksimali itampa'); %[output:6fd8bb36]
plot(ta(iMin), a(iMin), '^', 'Color', [0.5 0 0.5], 'MarkerSize', 9, ... %[output:6fd8bb36]
    'MarkerFaceColor', [0.5 0 0.5], 'DisplayName', 'Minimali itampa'); %[output:6fd8bb36]
yline(U1, 'Color', 'g', 'LineWidth', 1.5, 'DisplayName', 'Riba U_1'); %[output:6fd8bb36]
hold off; %[output:6fd8bb36]
grid on; %[output:6fd8bb36]
title('Pradinio signalo reiksmes, virsijancios U_1 riba'); %[output:6fd8bb36]
xlabel('Laikas, s', 'Color', 'b', 'FontSize', 12); %[output:6fd8bb36]
ylabel('Itampa, V', 'Color', 'b', 'FontSize', 12); %[output:6fd8bb36]
legend('Location', 'best'); %[output:6fd8bb36]
xlim([t(1) t(end)]); %[output:6fd8bb36]
ylim([U1 - 1, aMax + 1]); %[output:6fd8bb36]

